3	/// The Picture sub-tab's Background section (road map creator-jobs CO3, spec §11 CO-30): Remove
4	/// Background by Vision on the Mac, right after Chroma Key. The checkbox and Reset are the
5	/// clip's — a base `set_video` whatever is selected, so inside an action they are ⊘ — and
6	/// Background, Edge and Feather write a sparse `cutoutPart`, which an action animates (an end
7	/// gets only the row's own key). Status reads the pane's `CutoutStatus.Memo`; Analyze Now asks
8	/// the editor's `analyzeCutoutNow` (the wants made again, then a failed run retried). With every
9	/// selected clip a picture, Subject (Person, Foreground) follows the checkbox: the clip's, like
10	/// it (road map creator-jobs CO10b, spec §11 CO-108).
11	extension VideoPane {
12	
13	    /// Every selected clip can be cut out: a media or still clip of a video file with pictures,
14	    /// or an image clip of a picture (CO-108).
15	    var allCutoutable: Bool {
16	        let clips = binding.clips
17	        return !clips.isEmpty
18	            && clips.allSatisfy { CutoutStatus.canCutOut($0, in: binding.snapshot) }
19	    }
20	
21	    /// Every selected clip is an image clip — the Subject row's gate (CO-108).
22	    var allPictures: Bool {
23	        let clips = binding.clips
24	        return !clips.isEmpty && clips.allSatisfy {
25	            if case .image = $0.source { return true }
26	            return false
27	        }
28	    }
29	
30	    /// Every selected video clip has a BASE cutout — Background, Edge and Feather's gate.
31	    var allCutOut: Bool {
32	        let clips = binding.videoClips
33	        return !clips.isEmpty && clips.allSatisfy { $0.video?.cutout != nil }
34	    }
35	
36	    func cutoutSection(_ memo: CutoutStatus.Memo) -> InspectorSection {
37	        let binding = self.binding
38	        func anyOn() -> Bool { binding.videoClips.contains { $0.video?.cutout != nil } }
39	        func allOn() -> Bool { allCutOut }
40	        func cut() -> CutoutProps { binding.videoProps.cutout ?? CutoutProps() }
41	        func onOps() -> [ReelOp] {
42	            binding.videoClips.filter { $0.video?.cutout == nil }.flatMap {
43	                binding.ops(video: VideoPatch(cutout: .some(CutoutProps())), for: $0)
44	            }
45	        }
46	        // Base whatever is selected: `structural(video:for:)` sends a cutout's presence there.
47	        func offOps() -> [ReelOp] { binding.ops(video: VideoPatch(cutout: .some(nil))) }
48	        func part(_ patch: CutoutPatch) -> [ReelOp] {
49	            binding.ops(video: VideoPatch(cutoutPart: patch))
50	        }
51	        let enabled: () -> Bool = { [weak self] in self?.allCutOut ?? false }
52	        func single() -> (UInt32, ProjectDocument)? {
53	            guard binding.videoClips.count == 1, let clip = binding.videoClips.first,
54	                let document = binding.document
55	            else { return nil }
56	            return (clip.id, document)
57	        }
58	        func statusWords() -> String {
59	            guard let (clip, document) = single() else { return "—" }
60	            return CutoutStatus.words(memo.status(of: clip, in: document).state)
61	        }
62	        func analyzable() -> Bool {
63	            guard let document = binding.document else { return false }
64	            let states: [CutoutState]
65	            if let (clip, document) = single() {
66	                states = [memo.status(of: clip, in: document).state]
67	            } else {
68	                states = binding.videoClips.filter { $0.video?.cutout != nil }.map {
69	                    CutoutStatus.status(of: $0.id, in: document).state
70	                }
71	            }
72	            return states.contains {
73	                switch $0 {
74	                case .analyzing, .failed: return true
75	                default: return false
76	                }
77	            }
78	        }
79	
80	        let check = OptionCheckboxControl(
81	            label: "Remove background", read: allOn,
82	            write: { value in binding.apply("Remove Background", value ? onOps() : offOps()) },
83	            enabled: { true }, onEdit: { binding.edited() })
84	        weak var statusView: OptionDisplayControl?
85	        let readout = inspectorReadout(width: 170) {
86	            let words = statusWords()
87	            statusView?.toolTip = words
88	            if let statusView, let (clip, document) = single() {
89	                memo.watch(statusView, clip: clip, document: document)
90	            }
91	            return words
92	        }
93	        statusView = readout
94	        let analyze = OptionButtonControl(
95	            title: "Analyze Now",
96	            action: { [weak self] in
97	                self?.inspector?.onCommand?(#selector(EditorViewController.analyzeCutoutNow(_:)))
98	                memo.invalidate()
99	                binding.edited()
100	            },
101	            enabled: analyzable, onEdit: {})
102	        analyze.toolTip = "Make this clip's masks now, again after a failure"
103	        let backgrounds = CutoutBackground.allCases
104	        let subjects = CutoutSubject.allCases
105	        // The clip's subject, written whole on the BASE through `structural(video:for:)` —
106	        // a cutout's presence goes there, so the row is ⊘ inside an action (CO-108).
107	        func subjectOps(_ index: Int) -> [ReelOp] {
108	            guard subjects.indices.contains(index) else { return [] }
109	            return binding.videoClips.compactMap { clip -> [ReelOp]? in
110	                guard var base = clip.video?.cutout else { return nil }
111	                base.subject = subjects[index]
112	                return binding.ops(video: VideoPatch(cutout: .some(base)), for: clip)
113	            }.flatMap { $0 }
114	        }
115	        let subjectRow: [NSView] = allPictures
116	            ? [
117	                inspectorPopupRow(
118	                    "Subject", binding, name: "Cutout Subject", items: ["Person", "Foreground"],
119	                    read: { subjects.firstIndex(of: cut().subject) ?? 0 },
120	                    ops: subjectOps,
121	                    mixed: {
122	                        Set(binding.videoClips.compactMap { $0.video?.cutout?.subject }).count > 1
123	                    },
124	                    enabled: enabled)
125	            ] : []
126	        return InspectorSection(
127	            id: "video.cutout", title: "Background",
128	            summary: {
129	                guard anyOn() else { return "off" }
130	                return single() == nil ? "on" : statusWords()
131	            },
132	            reset: { binding.apply("Remove Background", offOps()) },
133	            defaultExpanded: false,
134	            rows: [
135	                inspectorRow(
136	                    nil, [check], mixed: { anyOn() && !allOn() }, binding: binding,
137	                    writes: offOps(),
138	                    default: InspectorRowDefault(
139	                        name: "Remove Background", differs: anyOn, ops: offOps)),
140	            ] + subjectRow + [
141	                inspectorPopupRow(
142	                    "Background", binding, name: "Cutout Background", items: ["Remove", "Keep"],
143	                    read: { backgrounds.firstIndex(of: cut().background) ?? 0 },
144	                    ops: { index in
145	                        guard backgrounds.indices.contains(index) else { return [] }
146	                        return part(CutoutPatch(background: backgrounds[index]))
147	                    },
148	                    mixed: { binding.mixedVideo { $0.cutout?.background } },
149	                    enabled: enabled),
150	                inspectorValueRow(
151	                    "Edge", binding, name: "Cutout Edge", decimals: 2, min: -1, max: 1,
152	                    quick: [-0.5, -0.25, 0, 0.25, 0.5],
153	                    read: { cut().edge },
154	                    ops: { part(CutoutPatch(edge: $0)) },
155	                    mixed: { binding.mixedVideo { $0.cutout?.edge } },
156	                    enabled: enabled),
157	                inspectorValueRow(
158	                    "Feather", binding, name: "Cutout Feather", unit: "%", decimals: 0,
159	                    min: 0, max: 100, quick: [0, 10, 25, 50],
160	                    read: { cut().feather * 100 },
161	                    ops: { part(CutoutPatch(feather: $0 / 100)) },
162	                    mixed: { binding.mixedVideo { $0.cutout?.feather } },
163	                    enabled: enabled),
164	                inspectorRow("Status", [readout]),
165	                inspectorButtonRow([analyze]),
166	            ])
167	    }
168	}
