3	/// The Picture sub-tab's Behind Subject section (road map creator-jobs CO5, spec §11 CO-55),
4	/// right after Transform: one checkbox writing `video.behind_subject` — an end inside an action,
5	/// where the flag switches at the action's end (CO-52) — one undo step "Behind Subject", mixed
6	/// over a selection that disagrees, Reset writing false. With one clip selected and its flag on,
7	/// a note says when no cut-out clip is behind it at the playhead: the document's recipe there
8	/// names no subject group in the clip's cut (`BehindSubjectPlan.isCutBySubject`).
9	extension VideoPane {
10	
11	    /// The section's gate: no nest open, and a selection with pixels holding no adjustment clip
12	    /// and no nest clip — the two kinds the core refuses the flag on (CO-52).
13	    var allBehindable: Bool {
14	        guard binding.document?.scope == nil else { return false }
15	        let clips = binding.clips
16	        return !clips.isEmpty && !binding.videoClips.isEmpty
17	            && !clips.contains { clip in
18	                if case .nest = clip.source { return true }
19	                return InspectorTab.isAdjustment(clip)
20	            }
21	    }
22	
23	    func behindSubjectSection() -> InspectorSection {
24	        let binding = self.binding
25	        func on() -> Bool { binding.videoProps.behindSubject }
26	        func ops(_ value: Bool) -> [ReelOp] {
27	            binding.ops(video: VideoPatch(behindSubject: value))
28	        }
29	        func note() -> String? {
30	            guard binding.isSingle, let clip = binding.videoClips.first, on(),
31	                let document = binding.document, document.scope == nil,
32	                let recipe = document.project.recipe(at: document.playhead)
33	            else { return nil }
34	            return BehindSubjectPlan.isCutBySubject(clip: clip.id, in: recipe) == true
35	                ? nil : "No cut-out clip is behind it at the playhead."
36	        }
37	        return InspectorSection(
38	            id: "video.behind_subject", title: "Behind Subject",
39	            summary: { on() ? "on" : "off" },
40	            note: note,
41	            reset: { binding.apply("Behind Subject", ops(false)) },
42	            defaultExpanded: false,
43	            rows: [
44	                inspectorCheckRow(
45	                    "Behind subject", binding, name: "Behind Subject", read: on, ops: ops,
46	                    mixed: { binding.mixedVideo { $0.behindSubject } })
47	            ])
48	    }
49	}
