92	        if targets.allSatisfy({ $0.video?.cutout != nil }) {
93	            return targets.map { .setVideo(clips: [$0.id], patch: VideoPatch(cutout: .some(nil))) }
94	        }
95	        return targets.filter { $0.video?.cutout == nil }.map {
96	            .setVideo(clips: [$0.id], patch: VideoPatch(cutout: .some(CutoutProps())))
97	        }
98	    }
