111	    // MARK: - The status (CO-31 (a))
112	
113	    /// `clip`'s status in `document`. Main thread.
114	    static func status(of clip: UInt32, in document: ProjectDocument) -> CutoutClipStatus {
115	        detail(of: clip, in: document).status
116	    }
117	
118	    /// `clip`'s status and what it was read from. Main thread.
119	    static func detail(of clip: UInt32, in document: ProjectDocument) -> Detail {
120	        let handles = document.scope == nil
121	            ? [document.project] : [document.project, document.editedProject]
122	        let owner = document.maskOwner
123	        var kind = AnalysisKind.masks
124	        func answer(
125	            _ state: CutoutState, media: MediaSnapshot? = nil, need: [ClosedRange<Int>] = [],
126	            coverage: [ClosedRange<Int>] = [], frames: Int = 0, covered: Int = 0,
127	            found: Bool = false, pack: URL? = nil, cache: URL? = nil
128	        ) -> Detail {
129	            var error: String?
130	            if case .failed(let why) = state {
131	                let noun = kind == .foreground ? "foreground" : "person"
132	                error = "Clip \(clip)'s \(noun) masks could not be made: \(why)."
133	            }
134	            return Detail(
135	                status: CutoutClipStatus(
136	                    clip: clip, media: media?.id, state: state, frames: frames, covered: covered,
137	                    subjectFound: found, error: error),
138	                media: media, need: need, coverage: coverage, pack: pack, owner: owner,
139	                cacheDir: cache, kind: kind)
140	        }
141	        let found = handles.lazy.compactMap { handle in
142	            (handle.snapshot.clips + handle.snapshot.nests.flatMap(\.clips)).first {
143	                $0.id == clip
144	            }
145	        }.first
146	        guard let snapshot = found, snapshot.video?.cutout != nil else { return answer(.off) }
147	        guard let id = snapshot.source.mediaID, let media = document.project.snapshot.media(id)
148	        else { return answer(.noPicture) }
149	        kind = CutoutWants.kind(of: snapshot)
150	        let grid = kind.grid(of: media)
151	        var windows: [CutoutWindow] = []
152	        var hull: ClosedRange<Ticks>?
153	        // A picture's one window `[0, 1)`, one frame (CO-106, CO-108).
154	        let picture: Bool
155	        if case .image = snapshot.source { picture = true } else { picture = false }
156	        for handle in handles where picture {
157	            windows += CutoutWants.imageWindows(snapshot: handle.snapshot, range: nil)
158	                .filter { $0.clip == clip && $0.media == id }
159	        }
160	        if picture, !windows.isEmpty { hull = 0...1 }
161	        for handle in handles where !picture {
162	            guard let plan = handle.plan else { continue }
163	            windows += CutoutWants.windows(plan: plan, snapshot: handle.snapshot, range: nil)
164	                .filter { $0.clip == clip && $0.media == id }
165	            if let window = CutoutPlan(plan: plan, snapshot: handle.snapshot)
166	                .window(clip: clip, media: id)
167	            {
168	                hull = hull.map {
169	                    min($0.lowerBound, window.lowerBound)...max($0.upperBound, window.upperBound)
170	                } ?? window
171	            }
172	        }
173	        let need = AnalysisStore.merged(windows.map { CutoutWants.need($0, grid: grid) })
174	        let frames = count(need)
175	        guard frames > 0 else { return answer(.noPicture, media: media) }
176	        let url = mediaURL(for: media)
177	        let cacheDir = document.intendedCacheDirectory
178	        let stamp = url.flatMap { url in
179	            cacheDir.flatMap {
180	                Self.stamp(media: media, url: url, cacheDir: $0, in: document, kind: kind)
181	            }
182	        }
183	        var coverage: [ClosedRange<Int>] = []
184	        var packURL: URL?
185	        if let stamp, let cacheDir,
186	            let marker = AnalysisStore.readMarker(kind, media: id, in: cacheDir),
187	            marker.answers(for: stamp), let file = marker.files.first
188	        {
189	            let payload = AnalysisStore.payloadURL(kind, media: id, file: file, in: cacheDir)
190	            if FileManager.default.fileExists(atPath: payload.path) {
191	                coverage = AnalysisStore.merged(marker.ranges)
192	                packURL = payload
193	            }
194	        }
195	        let covered = count(intersect(need, coverage))
196	        // Covered first: a clip whose masks are all stored is never failed by another
197	        // window's job (CO-31 (a)).
198	        if covered == frames {
199	            var subject = false
200	            if let packURL, let hull, let pack = try? MaskPack(contentsOf: packURL) {
201	                subject = CutoutLookup.subjectFound(
202	                    pack: pack, window: hull, coverage: coverage, grid: grid)
203	            }
204	            let none: CutoutState = kind == .foreground ? .noSubject : .noPerson
205	            return answer(
206	                subject ? .ready : none, media: media, need: need, coverage: coverage,
207	                frames: frames, covered: covered, found: subject, pack: packURL, cache: cacheDir)
208	        }
209	        func failed(_ why: String) -> Detail {
210	            answer(
211	                .failed(why), media: media, need: need, coverage: coverage, frames: frames,
212	                covered: covered, pack: packURL, cache: cacheDir)
213	        }
214	        guard url != nil else { return failed("the media file is missing") }
215	        guard let cacheDir else { return failed("no cache folder") }
216	        guard stamp != nil else { return failed("the media file cannot be read") }
217	        let requests = ownerRequests(owner, media: id, cacheDir: cacheDir, kind: kind)
218	        let uncovered = need.flatMap { AnalysisStore.missingRanges($0, covered: coverage) }
219	        for request in requests {
220	            guard case .failed(let why)? = AnalysisLane.shared.run(of: request)?.outcome,
221	                !intersect(uncovered, request.ranges).isEmpty
222	            else { continue }
223	            return failed(why)
224	        }
225	        let running = runningRequest(requests)
226	        let fraction = running.flatMap { AnalysisLane.shared.progress(of: $0) } ?? 0
227	        let progress = progress(
228	            need: need, covered: coverage, running: running?.ranges, fraction: fraction)
229	        return answer(
230	            .analyzing(progress), media: media, need: need, coverage: coverage, frames: frames,
231	            covered: covered, pack: packURL, cache: cacheDir)
232	    }
