234	    /// `owner`'s requests of `kind` of media `media` in `cacheDir`; none without an owner. Any
235	    /// thread.
236	    static func ownerRequests(
237	        _ owner: Int?, media: UInt32, cacheDir: URL, kind: AnalysisKind = .masks
238	    ) -> [AnalysisRequest] {
239	        guard let owner else { return [] }
240	        let folder = cacheDir.standardizedFileURL
241	        return AnalysisLane.shared.requests(of: owner).filter {
242	            $0.kind == kind && $0.media.id == media && $0.cacheDir.standardizedFileURL == folder
243	        }
244	    }
245	
246	    /// The first of `requests` started and not ended.
247	    static func runningRequest(_ requests: [AnalysisRequest]) -> AnalysisRequest? {
248	        requests.first { request in
249	            guard let run = AnalysisLane.shared.run(of: request) else { return false }
250	            return run.startedAt != nil && run.outcome == nil
251	        }
252	    }
