254	    /// The Status read-out's words (CO-30 (c)).
255	    static func words(_ state: CutoutState) -> String {
256	        switch state {
257	        case .off: return "Off"
258	        case .noPicture: return "No picture to analyze"
259	        case .analyzing(let progress):
260	            return "Analyzing \(min(99, max(0, Int((progress * 100).rounded(.down))))) %"
261	        case .ready: return "Ready"
262	        case .noPerson: return "No person found"
263	        case .noSubject: return "No subject found"
264	        case .failed(let why): return "Failed: \(why)"
265	        }
266	    }
