268	    // MARK: - Progress (CO-31 (a))
269	
270	    /// `(C_out + f · R_in) / N`: N the needed indices, R_in those inside `running`'s ranges,
271	    /// C_out the covered needed indices outside them; with no running request, C / N. Pure,
272	    /// 0…1.
273	    static func progress(
274	        need: [ClosedRange<Int>], covered: [ClosedRange<Int>], running: [ClosedRange<Int>]?,
275	        fraction: Double
276	    ) -> Double {
277	        let need = AnalysisStore.merged(need)
278	        let total = count(need)
279	        guard total > 0 else { return 0 }
280	        let coveredNeed = intersect(need, covered)
281	        let c = count(coveredNeed)
282	        guard let running else { return Double(c) / Double(total) }
283	        let rIn = count(intersect(need, running))
284	        let cOut = c - count(intersect(coveredNeed, running))
285	        let f = min(1, max(0, fraction))
286	        return min(1, max(0, (Double(cOut) + f * Double(rIn)) / Double(total)))
287	    }
288	
289	    /// How many indices `ranges` hold, merged first.
290	    static func count(_ ranges: [ClosedRange<Int>]) -> Int {
291	        AnalysisStore.merged(ranges).reduce(0) { $0 + $1.count }
292	    }
293	
294	    /// The indices both hold, merged.
295	    static func intersect(_ a: [ClosedRange<Int>], _ b: [ClosedRange<Int>])
296	        -> [ClosedRange<Int>]
297	    {
298	        let a = AnalysisStore.merged(a), b = AnalysisStore.merged(b)
299	        var out: [ClosedRange<Int>] = []
300	        var i = 0, j = 0
301	        while i < a.count, j < b.count {
302	            let low = max(a[i].lowerBound, b[j].lowerBound)
303	            let high = min(a[i].upperBound, b[j].upperBound)
304	            if low <= high { out.append(low...high) }
305	            if a[i].upperBound < b[j].upperBound { i += 1 } else { j += 1 }
306	        }
307	        return out
308	    }
309	
310	    // MARK: - The centroid (CO-31 (c))
311	
312	    /// The mean, over `pack`'s frames whose grid index lies in `need` and `coverage` and whose
313	    /// mask is `found`, of each frame's value-weighted centroid in mask texels (`Σ v·(x + 0.5) /
314	    /// Σ v`, likewise y), scaled to the media's upright pixels; nil when no frame counts. Any
315	    /// thread.
316	    static func centroid(
317	        pack: MaskPack, need: [ClosedRange<Int>], coverage: [ClosedRange<Int>],
318	        mediaWidth: Int, mediaHeight: Int
319	    ) throws -> CGPoint? {
320	        guard pack.width > 0, pack.height > 0 else { return nil }
321	        let need = AnalysisStore.merged(need), coverage = AnalysisStore.merged(coverage)
322	        var perSlot: [Int: (x: Double, y: Double)?] = [:]
323	        var sumX = 0.0, sumY = 0.0, frames = 0
324	        for frame in pack.frames {
325	            let index = Int(frame.index), slot = Int(frame.slot)
326	            guard need.contains(where: { $0.contains(index) }),
327	                coverage.contains(where: { $0.contains(index) }), pack.masks[slot].found
328	            else { continue }
329	            let point: (x: Double, y: Double)?
330	            if let known = perSlot[slot] {
331	                point = known
332	            } else {
333	                point = weighted(try pack.mask(slot: slot), width: pack.width, height: pack.height)
334	                perSlot[slot] = point
335	            }
336	            guard let point else { continue }
337	            sumX += point.x
338	            sumY += point.y
339	            frames += 1
340	        }
341	        guard frames > 0 else { return nil }
342	        return CGPoint(
343	            x: sumX / Double(frames) * Double(mediaWidth) / Double(pack.width),
344	            y: sumY / Double(frames) * Double(mediaHeight) / Double(pack.height))
345	    }
346	
347	    /// One mask's value-weighted centroid in texels; nil for an empty mask.
348	    private static func weighted(_ mask: [UInt8], width: Int, height: Int)
349	        -> (x: Double, y: Double)?
350	    {
351	        var total = 0.0, x = 0.0, y = 0.0
352	        for row in 0..<height {
353	            var rowSum = 0.0
354	            for column in 0..<width {
355	                let v = Double(mask[row * width + column])
356	                rowSum += v
357	                x += v * (Double(column) + 0.5)
358	            }
359	            total += rowSum
360	            y += rowSum * (Double(row) + 0.5)
361	        }
362	        guard total > 0 else { return nil }
363	        return (x / total, y / total)
364	    }
