3	/// `analyze_cutout` (road map creator-jobs CO3, spec §11 CO-31): the mirror of the Background
4	/// section's Status and Analyze Now. Off the main thread: one main hop names the clips, refuses
5	/// in CO-31 (b)'s order and runs `analyzeMasksNow()`; `CutoutWants.queue.sync {}` lets that
6	/// want and its retry run before the first read; then the statuses are read every 0.25 s on
7	/// main until every clip settles, `wait` passes or the assistant's Stop — never a timeout
8	/// refusal. The centroid is read here, off main, from the values captured on it.
9	extension AgentServer {
10	
11	    static let cutoutPollInterval: TimeInterval = 0.25
12	    static let cutoutWaitLimit: Double = 60
13	
14	    func analyzeCutout(_ a: [String: Any]) throws -> String {
15	        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
16	        guard !Thread.isMainThread else {
17	            throw ToolError(
18	                message: "analyze_cutout must run on the server thread — its name is missing "
19	                    + "from AgentServer.creatorOffMainTools.")
20	        }
21	        var wait = 0.0
22	        if let raw = a["wait"], !(raw is NSNull) {
23	            guard let number = raw as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID(),
24	                number.doubleValue.isFinite, number.doubleValue >= 0,
25	                number.doubleValue <= Self.cutoutWaitLimit
26	            else { throw ToolError(message: "wait must be from 0 to 60 seconds.") }
27	            wait = number.doubleValue
28	        }
29	        let (document, clips) = try onMain { () throws -> (ProjectDocument, [UInt32]) in
30	            let document = try target(a)
31	            let snapshot = document.editedProject.snapshot
32	            let cutOut = { (id: UInt32) in snapshot.clip(id)?.video?.cutout != nil }
33	            // A picture's masks are analysed as a movie's are (spec §11 CO-108, CO-103 lifted).
34	            let clips: [UInt32]
35	            if let named = try optionalClipsArg(a, "clips", document) {
36	                if let bare = named.first(where: { !cutOut($0) }) {
37	                    throw ToolError(
38	                        message: "Clip \(bare) has no Remove Background; set_video "
39	                            + "{cutout: {}} turns it on.")
40	                }
41	                clips = named
42	            } else {
43	                clips = snapshot.clips.filter { $0.video?.cutout != nil }
44	                    .sorted { ($0.start, $0.id) < ($1.start, $1.id) }.map(\.id)
45	                guard !clips.isEmpty else {
46	                    throw ToolError(
47	                        message: "No clip in the open scope has Remove Background on; "
48	                            + "set_video {cutout: {}} turns it on.")
49	                }
50	            }
51	            document.analyzeMasksNow()
52	            return (document, clips)
53	        }
54	        CutoutWants.queue.sync {}
55	        let deadline = Date().addingTimeInterval(wait)
56	        var read: (details: [CutoutStatus.Detail], qualities: [String], project: [String: Any])
57	        while true {
58	            read = onMain {
59	                let snapshot = document.editedProject.snapshot
60	                let details = clips.map { CutoutStatus.detail(of: $0, in: document) }
61	                let qualities = clips.map {
62	                    snapshot.clip($0)?.video?.cutout?.quality.rawValue
63	                        ?? CutoutQuality.standard.rawValue
64	                }
65	                return (details, qualities, summary(document))
66	            }
67	            if read.details.allSatisfy({ $0.status.state.isSettled }) || Date() >= deadline
68	                || stop?.isCancelled == true
69	            {
70	                break
71	            }
72	            Thread.sleep(forTimeInterval: Self.cutoutPollInterval)
73	        }
74	        let rows = zip(read.details, read.qualities).map { Self.cutoutRow($0, quality: $1) }
75	        return try jsonResult(["ok": true, "clips": rows, "project": read.project])
76	    }
77	
78	    /// One clip's answer (CO-31 (c)), its centroid read from the pack here.
79	    private static func cutoutRow(_ detail: CutoutStatus.Detail, quality: String) -> [String: Any] {
80	        let status = detail.status
81	        let state: String
82	        var progress = status.frames > 0 ? Double(status.covered) / Double(status.frames) : 0
83	        switch status.state {
84	        case .off: state = "off"
85	        case .noPicture: state = "no_picture"
86	        case .analyzing(let value):
87	            state = "analyzing"
88	            progress = value
89	        case .ready: state = "ready"
90	        case .noPerson: state = "no_person"
91	        case .noSubject: state = "no_subject"
92	        case .failed: state = "failed"
93	        }
94	        var centroid: Any = NSNull()
95	        if status.state == .ready, status.subjectFound, let url = detail.pack,
96	            let media = detail.media, let pack = try? MaskPack(contentsOf: url),
97	            let point = try? CutoutStatus.centroid(
98	                pack: pack, need: detail.need, coverage: detail.coverage,
99	                mediaWidth: media.width, mediaHeight: media.height)
100	        {
101	            centroid = ["x": Double(point.x), "y": Double(point.y)]
102	        }
103	        var row: [String: Any] = [
104	            "clip": Int(status.clip), "media": status.media.map { Int($0) } ?? NSNull(),
105	            "state": state, "progress": (progress * 1000).rounded() / 1000, "quality": quality,
106	            "frames": status.frames, "covered": status.covered,
107	            "ready": status.frames > 0 && status.covered == status.frames,
108	            "subject_found": status.subjectFound, "centroid": centroid,
109	        ]
110	        if let error = status.error { row["error"] = error }
111	        return row
112	    }
113	}
