10	/// A clip's cutout state (CO-30 (c), CO-31 (a)).
11	enum CutoutState: Equatable {
12	    case off
13	    case noPicture
14	    /// 0…1, CO-31 (a)'s progress.
15	    case analyzing(Double)
16	    case ready
17	    case noPerson
18	    /// A picture cut by its foreground whose mask found none (spec §11 CO-108).
