52	enum CutoutStatus {
53	
54	    /// What a status was read from: the media, the needed ranges, the stored coverage and the
55	    /// pack's file, and the document's lane owner — what the read-out's tick recomputes the
56	    /// progress from and `analyze_cutout` reads the centroid from, off main.
57	    struct Detail {
58	        let status: CutoutClipStatus
59	        let media: MediaSnapshot?
60	        let need: [ClosedRange<Int>]
61	        let coverage: [ClosedRange<Int>]
62	        let pack: URL?
63	        let owner: Int?
64	        /// The document's cache folder, when the status read one.
65	        let cacheDir: URL?
