70	    // MARK: - Which clips
71	
72	    /// A media or still clip of a video file with pictures (CO-30 (a)), or an image clip of a
73	    /// picture (CO-108).
74	    static func canCutOut(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
75	        switch clip.source {
76	        case .media, .still:
77	            guard let media = snapshot.media(for: clip) else { return false }
78	            return media.kind == .video && media.hasVideo
79	        case .image:
80	            return snapshot.media(for: clip)?.kind == .image
81	        default:
82	            return false
83	        }
84	    }
