86	    /// Clip ▸ Remove Background's edit (CO-30 (e)): with every clip that can be cut out already
87	    /// cut out, a null to each; otherwise a whole default cutout to each one without. One base
88	    /// `set_video` per clip.
89	    static func toggleOps(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot) -> [ReelOp] {
90	        let targets = clips.filter { canCutOut($0, in: snapshot) }
91	        guard !targets.isEmpty else { return [] }
92	        if targets.allSatisfy({ $0.video?.cutout != nil }) {
93	            return targets.map { .setVideo(clips: [$0.id], patch: VideoPatch(cutout: .some(nil))) }
94	        }
95	        return targets.filter { $0.video?.cutout == nil }.map {
96	            .setVideo(clips: [$0.id], patch: VideoPatch(cutout: .some(CutoutProps())))
97	        }
98	    }
