100	    /// The menu item's checkmark: on when every clip that can be cut out is, mixed when some
101	    /// are, off when none is (or none can be).
102	    static func menuState(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot)
103	        -> NSControl.StateValue
104	    {
105	        let targets = clips.filter { canCutOut($0, in: snapshot) }
106	        let on = targets.filter { $0.video?.cutout != nil }.count
107	        if on == 0 { return .off }
108	        return on == targets.count ? .on : .mixed
