366	    // MARK: - The stamp, once per cache folder, media and URL (main only)
367	
368	    private struct StampKey: Hashable {
369	        let folder: String
370	        let kind: AnalysisKind
371	        let media: UInt32
372	        let url: URL
373	    }
374	
375	    private struct StampEntry {
376	        let media: MediaSnapshot
377	        let lut: URL?
378	        let stamp: AnalysisStamp?
379	    }
380	
381	    private static var stamps: [StampKey: StampEntry] = [:]
382	
383	    /// The stamp of `kind` `ProjectDocument.analysisRequest` would make for `media` at `url`:
384	    /// its asset read only when the media, its URL or its LUT's URL changed. Main thread.
385	    static func stamp(
386	        media: MediaSnapshot, url: URL, cacheDir: URL, in document: ProjectDocument,
387	        kind: AnalysisKind = .masks
388	    ) -> AnalysisStamp? {
389	        let lutID = media.color?.lut
390	        let lut = lutID.flatMap { document.project.snapshot.media($0) }.flatMap(mediaURL(for:))
391	        let key = StampKey(
392	            folder: cacheDir.standardizedFileURL.path, kind: kind, media: media.id, url: url)
393	        if let entry = stamps[key], entry.media == media, entry.lut == lut { return entry.stamp }
394	        var urls = [media.id: url]
395	        if let lutID, let lut { urls[lutID] = lut }
396	        let (input, fullRange) = ProjectDocument.analysisInput(media: media, url: url, urls: urls)
397	        let stamp = AnalysisStamp.make(
398	            kind: kind, media: media, url: url, input: input, fullRange: fullRange)
399	        stamps[key] = StampEntry(media: media, lut: lut, stamp: stamp)
400	        return stamp
401	    }
402	}
