78	    /// One clip's answer (CO-31 (c)), its centroid read from the pack here.
79	    private static func cutoutRow(_ detail: CutoutStatus.Detail, quality: String) -> [String: Any] {
80	        let status = detail.status
81	        let state: String
82	        var progress = status.frames > 0 ? Double(status.covered) / Double(status.frames) : 0
83	        switch status.state {
84	        case .off: state = "off"
85	        case .noPicture: state = "no_picture"
86	        case .analyzing(let value):
87	            state = "analyzing"
88	            progress = value
89	        case .ready: state = "ready"
90	        case .noPerson: state = "no_person"
91	        case .noSubject: state = "no_subject"
92	        case .failed: state = "failed"
93	        }
94	        var centroid: Any = NSNull()
95	        if status.state == .ready, status.subjectFound, let url = detail.pack,
96	            let media = detail.media, let pack = try? MaskPack(contentsOf: url),
97	            let point = try? CutoutStatus.centroid(
98	                pack: pack, need: detail.need, coverage: detail.coverage,
99	                mediaWidth: media.width, mediaHeight: media.height)
100	        {
101	            centroid = ["x": Double(point.x), "y": Double(point.y)]
102	        }
103	        var row: [String: Any] = [
104	            "clip": Int(status.clip), "media": status.media.map { Int($0) } ?? NSNull(),
105	            "state": state, "progress": (progress * 1000).rounded() / 1000, "quality": quality,
106	            "frames": status.frames, "covered": status.covered,
107	            "ready": status.frames > 0 && status.covered == status.frames,
108	            "subject_found": status.subjectFound, "centroid": centroid,
109	        ]
110	        if let error = status.error { row["error"] = error }
111	        return row
