94	/// `layer`'s `matte` with `ids` added to its `cut`, ascending.
95	fn cut_by(layer: &mut Value, ids: &[u64]) {
96	    let Value::Object(object) = layer else {
97	        return;
98	    };
99	    let mut cut: Vec<u64> = object
100	        .get("matte")
