102	        .and_then(Value::as_array)
103	        .into_iter()
104	        .flatten()
105	        .filter_map(Value::as_u64)
106	        .collect();
107	    cut.extend_from_slice(ids);
108	    cut.sort_unstable();
109	    let into = object
110	        .get("matte")
111	        .and_then(|m| m.get("into"))
112	        .cloned()
113	        .unwrap_or(Value::Null);
114	    let mut matte = Map::new();
115	    matte.insert("into".to_string(), into);
116	    matte.insert(
117	        "cut".to_string(),
118	        Value::Array(cut.into_iter().map(Value::from).collect()),
119	    );
120	    object.insert("matte".to_string(), Value::Object(matte));
