1701	/// by r0: `edge` moves the threshold (`c = 0.5 − 0.5·edge`, so a positive edge
1702	/// grows the outline), `feather` widens the ramp (`w = 0.5 + 0.5·feather`).
1703	static inline float cutoutCover(texture2d<float> mask, sampler samp, float2 uv,
1704	                                constant LayerUniforms &u) {
