1707	    float w = 0.5 + 0.5 * clamp(u.cutoutFeather, 0.0, 1.0);
1708	    float lo = clamp(c - w * 0.5, 0.0, 1.0);
1709	    float hi = clamp(c + w * 0.5, 0.0, 1.0);
1710	    return smoothstep(lo, hi, m);
1711	}
