48	/// Whether a layer object carries a cutout (`cutout` non-null).
49	fn has_cutout(layer: &Value) -> bool {
50	    layer.get("cutout").is_some_and(|c| !c.is_null())
51	}
52	
53	/// The ids a layer's `matte` names, `into` and `cut` alike.
54	fn named_ids(layer: &Value) -> impl Iterator<Item = u64> + '_ {
55	    let matte = layer.get("matte");
56	    let into = matte.and_then(|m| m.get("into")).and_then(Value::as_u64);
57	    let cut = matte
58	        .and_then(|m| m.get("cut"))
59	        .and_then(Value::as_array)
60	        .into_iter()
61	        .flatten()
62	        .filter_map(Value::as_u64);
63	    into.into_iter().chain(cut)
64	}
65	
66	/// The track-matte cut of a layer: its `matte.cut`, or none.
67	fn track_cut(layer: &Value) -> Value {
68	    layer
69	        .get("matte")
70	        .and_then(|m| m.get("cut"))
71	        .cloned()
72	        .unwrap_or_else(|| Value::Array(Vec::new()))
73	}
74	
75	/// The subject copy of `layer`, drawn into group `group` (CO-51).
76	fn subject_copy(layer: &Value, group: u64) -> Value {
77	    let mut copy = layer.clone();
78	    if let Value::Object(object) = &mut copy {
79	        let mut matte = Map::new();
80	        matte.insert("into".to_string(), Value::from(group));
81	        matte.insert("cut".to_string(), track_cut(layer));
82	        object.insert("blend".to_string(), Value::from("normal"));
83	        object.insert("shadow".to_string(), Value::Null);
84	        object.insert("reflection".to_string(), Value::Null);
85	        object.insert("matte".to_string(), Value::Object(matte));
86	        if let Some(Value::Object(cutout)) = object.get_mut("cutout") {
87	            cutout.insert("background".to_string(), Value::from("remove"));
88	            cutout.insert("subject_copy".to_string(), Value::Bool(true));
89	        }
90	    }
91	    copy
92	}
93	
94	/// `layer`'s `matte` with `ids` added to its `cut`, ascending.
95	fn cut_by(layer: &mut Value, ids: &[u64]) {
96	    let Value::Object(object) = layer else {
97	        return;
98	    };
99	    let mut cut: Vec<u64> = object
100	        .get("matte")
101	        .and_then(|m| m.get("cut"))
102	        .and_then(Value::as_array)
103	        .into_iter()
104	        .flatten()
105	        .filter_map(Value::as_u64)
106	        .collect();
107	    cut.extend_from_slice(ids);
108	    cut.sort_unstable();
109	    let into = object
110	        .get("matte")
111	        .and_then(|m| m.get("into"))
112	        .cloned()
113	        .unwrap_or(Value::Null);
114	    let mut matte = Map::new();
115	    matte.insert("into".to_string(), into);
116	    matte.insert(
117	        "cut".to_string(),
118	        Value::Array(cut.into_iter().map(Value::from).collect()),
119	    );
120	    object.insert("matte".to_string(), Value::Object(matte));
121	}
