124	    /// The subjects at the instant `instances` cover, merged into the
125	    /// recipe's layers, their Show Selection facts and `mattes` (module
126	    /// doc). `layers` and `facts` are aligned with `instances`; the answer's
127	    /// two lists are aligned with each other.
128	    pub(crate) fn frame_subjects(
129	        &self,
130	        instances: &[Instance<'_>],
131	        t: Ticks,
132	        layers: Vec<Value>,
133	        facts: Vec<LayerFacts>,
134	        mattes: Value,
135	    ) -> (Vec<Value>, Vec<LayerFacts>, Value) {
136	        // The cheap test first: no cutout on the frame, nothing to evaluate.
137	        if !layers.iter().any(has_cutout) {
138	            return (layers, facts, mattes);
139	        }
140	        let drawn_into = |i: usize| facts.get(i).is_some_and(|f| f.drawn_into);
141	        let behind: Vec<usize> = instances
142	            .iter()
143	            .enumerate()
144	            .filter(|(i, instance)| {
145	                !drawn_into(*i)
146	                    && !is_adjustment(instance.clip)
147	                    && self
148	                        .evaluate_clip(instance.clip, instance.clip_time(t))
149	                        .video
150	                        .behind_subject
151	            })
152	            .map(|(i, _)| i)
153	            .collect();
154	        if behind.is_empty() {
155	            return (layers, facts, mattes);
156	        }
157	        let subjects: Vec<usize> = (0..instances.len())
158	            .filter(|i| !drawn_into(*i) && layers.get(*i).is_some_and(has_cutout))
159	            .collect();
160	
161	        // Which subjects cut which behind layers; a subject is listed only
162	        // when it cuts one.
163	        let mut cuts: Vec<Vec<usize>> = vec![Vec::new(); instances.len()];
164	        let mut listed: Vec<usize> = Vec::new();
165	        for &s in &subjects {
166	            let Some(subject) = instances.get(s) else {
167	                continue;
168	            };
169	            let mut any = false;
170	            for &b in &behind {
171	                let Some(target) = instances.get(b) else {
172	                    continue;
173	                };
174	                if self.subject_behind(subject, target) {
175	                    if let Some(list) = cuts.get_mut(b) {
176	                        list.push(s);
177	                    }
178	                    any = true;
179	                }
180	            }
181	            if any {
182	                listed.push(s);
183	            }
184	        }
185	        if listed.is_empty() {
186	            return (layers, facts, mattes);
187	        }
188	
189	        let first = layers
190	            .iter()
191	            .flat_map(named_ids)
192	            .max()
193	            .map_or(0, |largest| largest + 1);
194	        let group_of = |s: usize| -> Option<u64> {
195	            listed
196	                .iter()
197	                .position(|l| *l == s)
198	                .map(|k| first + k as u64)
199	        };
200	
201	        let mut out_layers = Vec::with_capacity(layers.len() + listed.len());
202	        let mut out_facts = Vec::with_capacity(layers.len() + listed.len());
203	        for (i, (mut layer, fact)) in layers.into_iter().zip(facts).enumerate() {
204	            let copy = group_of(i).map(|group| (subject_copy(&layer, group), fact.clip));
205	            if let Some(list) = cuts.get(i).filter(|list| !list.is_empty()) {
206	                let ids: Vec<u64> = list.iter().filter_map(|s| group_of(*s)).collect();
207	                cut_by(&mut layer, &ids);
208	            }
209	            out_layers.push(layer);
210	            out_facts.push(fact);
211	            if let Some((copy, clip)) = copy {
212	                out_layers.push(copy);
213	                out_facts.push(LayerFacts {
214	                    clip,
215	                    top_adjustment: false,
216	                    drawn_into: true,
217	                });
218	            }
219	        }
220	
221	        let mut groups = match mattes {
222	            Value::Array(groups) => groups,
223	            _ => Vec::new(),
224	        };
225	        for k in 0..listed.len() {
226	            let mut entry = Map::new();
227	            entry.insert("group".to_string(), Value::from(first + k as u64));
228	            entry.insert("mode".to_string(), json(&TrackMatte::AlphaInverted));
229	            groups.push(Value::Object(entry));
230	        }
231	        (out_layers, out_facts, Value::Array(groups))
232	    }
