234	    /// Whether `subject` is behind `behind` in `behind`'s own container
235	    /// (module doc): at least as deep, inside the same nest clips down to
236	    /// `behind`'s depth, and on a track (at that depth) behind its track.
237	    fn subject_behind(&self, subject: &Instance<'_>, behind: &Instance<'_>) -> bool {
238	        let depth = behind.inside.len();
239	        if subject.inside.len() < depth {
240	            return false;
241	        }
242	        let same_nests = subject
243	            .inside
244	            .iter()
245	            .zip(&behind.inside)
246	            .all(|(s, b)| s.clip.id == b.clip.id);
247	        if !same_nests {
248	            return false;
249	        }
250	        let level_track = match subject.inside.get(depth) {
251	            Some(enclosing) => enclosing.track.id,
252	            None => subject.track.id,
253	        };
254	        let tracks: &[Track] = match depth.checked_sub(1) {
255	            Some(up) => match behind.inside.get(up) {
256	                Some(enclosing) => &enclosing.nest.tracks,
257	                None => return false,
258	            },
259	            None => &self.tracks,
