135	            for (media, need) in byMedia { needs[MaskKey(kind: kind, media: media)] = need }
136	        }
137	        let (requests, failures) = CutoutWants.wants(
138	            windows: windows, snapshot: snapshot, urls: urls, cacheDir: cacheDir)
139	        let unreadable = Set(failures.compactMap { failure in
140	            windows.first { $0.clip == failure.clip }.map { MaskKey(kind: $0.kind, media: $0.media) }
141	        })
142	        guard !requests.isEmpty else { return clips(of: unreadable) }
143	        // Each waited media's stamp, made once by its request; the polls only look up.
144	        var stamps: [MaskKey: AnalysisStamp] = [:]
145	        for request in requests {
146	            stamps[MaskKey(kind: request.kind, media: request.media.id)] = request.stamp
147	        }
