149	            Set(stamps.filter { key, stamp in
150	                (needs[key] ?? []).contains {
151	                    if case .hit = AnalysisStore.lookup(
152	                        key.kind, media: key.media, stamp: stamp, need: $0, in: cacheDir)
153	                    {
154	                        return false
155	                    }
156	                    return true
157	                }
158	            }.keys)
159	        }
