161	        defer { AnalysisLane.shared.release(owner: owner) }
162	        AnalysisLane.shared.want(requests, owner: owner, alive: { true }, settled: nil)
163	        #if FRAMEJOB_DEV_TOOLS
164	        CutoutWants.log(.frame, owner: owner, requests)
165	        #endif
166	        let deadline = Date().addingTimeInterval(limit)
167	        var missing = uncovered()
168	        while !missing.isEmpty, Date() < deadline,
169	            !requests.contains(where: {
